#!/usr/bin/env bash
# Smoke: health, snapshot LIVE≥8, screens, home, RESEARCH≥150, DESIGN+README
set -euo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd)"
BASE="${BASE_URL:-http://127.0.0.1:4335}"
FAIL=0
PASS=0

ok() { echo "OK  $*"; PASS=$((PASS+1)); }
bad() { echo "FAIL $*"; FAIL=$((FAIL+1)); }


# Fold-paint checks read static files (same as brief-019+). Home HTTP 200 already covers serving;
# curl|/ under heavy ThreadingHTTPServer smoke was flaking with truncated bodies.
ui_rg() { rg -q "$1" "$ROOT/static/index.html"; }
js_rg() { rg -q "$1" "$ROOT/static/app.js"; }

echo "== Starship Mission Control smoke =="

need_file() {
  local f="$1"
  if [[ -f "$ROOT/$f" ]]; then ok "file $f"; else bad "missing $f"; fi
}

need_file "README.md"
need_file "DESIGN.md"
need_file "RESEARCH.md"
need_file "server.py"
need_file "run.sh"
need_file "data/snapshot.json"
need_file "static/index.html"
need_file "static/styles.css"
need_file "static/app.js"

if [[ -f "$ROOT/RESEARCH.md" ]]; then
  lines=$(wc -l < "$ROOT/RESEARCH.md" | tr -d ' ')
  echo "RESEARCH.md lines=$lines"
  if [[ "$lines" -ge 150 ]]; then ok "RESEARCH.md ≥150"; else bad "RESEARCH.md lines=$lines (<150)"; fi
fi

# LIVE vs SYNTHETIC labels present in snapshot
python3 - <<'PY' && ok "snapshot LIVE≥8 + SYNTHETIC present" || bad "snapshot tags"
import json
from pathlib import Path
snap = json.loads(Path("data/snapshot.json").read_text(encoding="utf-8"))
live = 0
synth = 0
for L in snap["launches"]:
    live += L.get("tag")=="LIVE"; synth += L.get("tag")=="SYNTHETIC"
for m in snap["starlink"]["metrics"]:
    live += m.get("tag")=="LIVE"
for m in snap["milestones"]:
    live += m.get("tag")=="LIVE"
for t in snap["themes"]:
    live += t.get("tag")=="LIVE"; synth += t.get("tag")=="SYNTHETIC"
for s in snap["starlink"]["shells"]:
    live += s.get("tag")=="LIVE"
if snap["starlink"]["recent_mission"].get("tag")=="LIVE":
    live += 1
for w in snap["why_parenta_cares"]:
    synth += w.get("tag")=="SYNTHETIC"
assert live >= 8, live
assert synth >= 1, synth
assert len(snap["launches"]) >= 4
assert len(snap["themes"]) >= 4
assert len(snap["why_parenta_cares"]) >= 3
print(f"live={live} synth={synth} launches={len(snap['launches'])}")
PY

health=$(curl -s -o /tmp/smc-health.json -w "%{http_code}" "$BASE/api/health" || echo "000")
[[ "$health" == "200" ]] && ok "health $(cat /tmp/smc-health.json | python3 -c 'import sys,json;d=json.load(sys.stdin);print(d.get("service"),"live",d.get("live_fact_count"))')" || bad "health HTTP $health"

home=$(curl -s -o /dev/null -w "%{http_code}" "$BASE/" || echo "000")
[[ "$home" == "200" ]] && ok "home" || bad "home HTTP $home"

for ep in /api/snapshot /api/launches /api/starlink /api/themes /api/why /api/screens; do
  code=$(curl -s -o "/tmp/smc-${ep//\//_}.json" -w "%{http_code}" "$BASE$ep" || echo "000")
  [[ "$code" == "200" ]] && ok "$ep" || bad "$ep HTTP $code"
done

python3 - <<'PY' && ok "API payload shapes" || bad "API payloads"
import json
from pathlib import Path
snap = json.load(open("/tmp/smc-_api_snapshot.json", encoding="utf-8"))
assert snap["ok"] and snap["live_fact_count"] >= 8
assert "snapshot" in snap and "launches" in snap["snapshot"]
screens = json.load(open("/tmp/smc-_api_screens.json", encoding="utf-8"))
ids = {s["id"] for s in screens["screens"]}
assert ids >= {"countdown","starlink","themes","why"}, ids
print("screens", sorted(ids), "live", snap["live_fact_count"])
PY

# DESIGN anti-purple / ops wall tokens
python3 - <<'PY' && ok "DESIGN ops-wall (no purple SaaS)" || bad "DESIGN palette"
from pathlib import Path
css = Path("static/styles.css").read_text(encoding="utf-8")
design = Path("DESIGN.md").read_text(encoding="utf-8")
assert "#0e1114" in css or "--bg:" in css
assert "IBM Plex" in css or "IBM Plex" in design
# no classic purple gradient SaaS tells in shipped CSS
assert "purple" not in css.lower()
assert "#7c3aed" not in css and "#8b5cf6" not in css
assert "ops" in design.lower() or "wall" in design.lower()
print("palette ok")
PY

# README has 2-min how-to
python3 - <<'PY' && ok "README how-to" || bad "README how-to"
from pathlib import Path
t = Path("README.md").read_text(encoding="utf-8")
assert "./run.sh" in t
assert "4335" in t
assert "2-min" in t.lower() or "two minute" in t.lower() or "2 min" in t.lower()
print("readme ok", len(t.splitlines()), "lines")
PY


# --- brief-019 fold ---
need_file "data/brief019.json"

python3 - <<'PY' && ok "brief019.json law shape" || bad "brief019.json law shape"
import json
from pathlib import Path
b = json.loads(Path("data/brief019.json").read_text(encoding="utf-8"))
assert b["brief_id"] == "brief-019"
assert b["never_fabricate_telemetry"]["value"] == 0
assert b["scorecard"]["never_fabricate_telemetry"] == 0
assert b["scorecard"]["mission_ready_without_gates"] == 0
assert b["scorecard"]["fake_live_badges"] == 0
assert b["scorecard"]["auto_announce"] == 0
assert b["scorecard"]["timezone"] == "America/New_York"
assert b["public_data_only"] is True
for p in (
    "/api/mission-ready-force",
    "/api/fabricate",
    "/api/send",
    "/api/publish",
    "/api/overwrite",
    "/api/mutate",
):
    assert p in b["refused_post_prefixes"], p
assert "G2_official_clock" in b["mission_ready_gates"]["gates"]
assert "NET_UNOFFICIAL" in b["tower_chopsticks_sm"]["states"]
print("brief019 law ok")
PY

if rg -q "Brief-019 law · mission-ready gates" "$ROOT/static/index.html"; then ok "UI Brief-019 law panel"
else bad "UI missing Brief-019 law panel"; fi

code=$(curl -s -o /tmp/smc-b19.json -w "%{http_code}" "$BASE/api/brief019" || echo "000")
if [[ "$code" == "200" ]]; then ok "GET /api/brief019 $code"; else bad "GET /api/brief019 HTTP $code"; fi

python3 - <<'PY' && ok "brief-019 law + live_check" || bad "brief019 law + live_check"
import json
b = json.load(open("/tmp/smc-b19.json", encoding="utf-8"))
assert b["brief_id"] == "brief-019"
lc = b["live_check"]
assert lc["never_fabricate_telemetry"] == 0
assert lc["fake_live_badges"] == 0
assert lc["fabricated_live_rows"] == 0
assert lc["live_facts_incomplete"] == 0
assert lc["live_facts_ok"] >= 8
assert lc["synthetic_labeled"] >= 1
assert lc["synthetic_mislabel"] == 0
assert lc["mission_ready_force_succeed"] is False
assert lc["fabricate_apis_succeed"] is False
assert lc["mutation_endpoints_policy"] == "403"
assert lc["auto_announce"] == 0
assert lc["public_data_only"] is True
assert lc["timezone"] == "America/New_York"
assert "/api/mission-ready-force" in lc["refused_post_prefixes"]
assert "/api/fabricate" in lc["refused_post_prefixes"]
assert "/api/send" in lc["refused_post_prefixes"]
assert "/api/publish" in lc["refused_post_prefixes"]
assert "/api/overwrite" in lc["refused_post_prefixes"]
assert "/api/mutate" in lc["refused_post_prefixes"]
tower = lc["tower_sm"]
assert tower["provenance"] == "ILLUSTRATIVE"
assert tower["state"] in (
    "PAD_QUIET","VEHICLE_NAMED","STATIC_FIRE_REPORTED","NET_UNOFFICIAL",
    "NET_OFFICIAL","WEBCAST_LIVE","CATCH_INTENT_STATED","CATCH_WINDOW_OPEN",
    "OUTCOME_HUMAN_CONFIRMED","UNKNOWN",
)
# Flight 15 has no official SpaceX clock → READY denied
assert lc["mission_ready"] is False
assert lc["mission_ready_denied"] is True
assert "G2_official_clock" in lc["failed_gates"]
assert lc["hero_official_clock_enabled"] is False
assert b["scorecard"]["never_fabricate_telemetry"] == 0
assert b["scorecard"]["mission_ready_without_gates"] == 0
print("brief019_ok", lc.get("served_at_et"), "gates", lc["gates_passed"], "/", lc["gates_total"], "tower", tower["state"])
PY

deny_ok=0
for deny in /api/mission-ready-force /api/coverage-force /api/fabricate-coverage /api/availability-claim /api/fabricate /api/send /api/publish /api/overwrite /api/mutate; do
  c=$(curl -s -o /tmp/smc-post-deny.json -w "%{http_code}" -X POST -H 'Content-Type: application/json' -d '{}' "$BASE$deny" || echo "000")
  if [[ "$c" == "403" ]]; then deny_ok=$((deny_ok+1)); else echo "  deny $deny -> HTTP $c"; fi
done
[[ "$deny_ok" -eq 9 ]] && ok "mutation POSTs refused 403 ($deny_ok/9)" || bad "mutation POSTs refused 403 ($deny_ok/9)"

if rg -qi "brief-019|brief-020|brief-026|refused|never_fabricate|fabricate_telemetry|mission-ready|coverage" /tmp/smc-post-deny.json; then ok "POST body cites brief refuse"
else bad "POST body missing brief refuse"; fi

if rg -q 'brief-019|Brief-019|mission-ready gates|never_fabricate_telemetry' "$ROOT/README.md"; then ok "README brief-019 fold note"
else bad "README missing brief-019 fold note"; fi

