assert b["brief_id"] == "brief-117"
sc = b["scorecard"]; lc = b["live_check"]
assert lc.get("ok") is True
assert sc["fabricate_refusal"] == 0 and lc["fabricate_refusal"] == 0
assert sc["dual_proof_required"] == 1 and lc["dual_proof_required"] == 1
assert sc["fake_live_refusal"] == 0 and lc["fake_live_refusal"] == 0
assert sc["single_digest_live"] == 0 and lc["single_digest_live"] == 0
assert sc["mismatch_auto_pick"] == 0 and lc["mismatch_auto_pick"] == 0
assert sc["merge_apply"] is False and lc["merge_apply"] is False
for k in ("fabricate_digest","reuse_stale_digest","hold_timeout_refusal","burn_outbound","auto_text_kids","auto_text_flight15"):
