assert sc.get("review_private_default") == 1
assert lc["fake_live"] == 0
assert lc.get("live_refusal") is False
assert lc.get("live_paint") is False
assert (lc.get("live_refusal_row_paint") or lc.get("live_refusal_paint") or {}).get("allowed") is False
