    assert cous.get(c, {}).get("merge_apply") is False, c
assert lc["timezone"] == "America/New_York"
assert lc["home"] == "Hometown, MD" or lc.get("place") == "Hometown, MD"
assert lc["pairs_brief098"] is True and lc["pairs_brief091"] is True
assert lc["mutation_endpoints_policy"] == "403"
assert lc.get("example_only") is True
assert b.get("pipeline_version") == "v1.116.0"
