import json, urllib.request
req = urllib.request.Request(
    "http://127.0.0.1:4335/api/single-digest-live-print-kit-refusal-paint-dual-proof",
    data=json.dumps({"hold": True}).encode(),
    headers={"Content-Type": "application/json"},
    method="POST",
)
try:
    with urllib.request.urlopen(req) as r:
        body = r.read(); code = r.status
except Exception as e:
    code = getattr(e, "code", None)
    body = getattr(e, "read", lambda: b"{}")()
assert code == 403, code
b = json.loads(body.decode() if isinstance(body, (bytes, bytearray)) else body)
assert b.get("brief_id") == "brief-148"
assert b.get("merge_apply") is False
